export class SartorialKnowledgeEngine {
  public getRuleByCode(code: string): SartorialRuleItem | undefined {
    return SARTORIAL_RULEBOOK_DATABASE.find(r => r.ruleCode === code);
  }
  public getRulesByCategory(category: string): SartorialRuleItem[] {
    return SARTORIAL_RULEBOOK_DATABASE.filter(r => r.category === category);
  }
}
export const sartorialKnowledgeEngine = new SartorialKnowledgeEngine();
